import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"协同行动","description":"","frontmatter":{},"headers":[],"relativePath":"guide/chain-action.md","filePath":"guide/chain-action.md","lastUpdated":1791903058000}'),o={name:"guide/chain-action.md"};function i(h,t,c,l,n,p){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="协同行动" tabindex="-1">协同行动 <a class="header-anchor" href="#协同行动" aria-label="Permalink to &quot;协同行动&quot;">​</a></h1><p>协同行动让队友在别人的回合提前出手。当前回合角色 A 确认申请，协作方 B 使用自己的决策点与配额执行动作；即时动作完成后，继续由 A 决策。</p><h2 id="谁可以协作" tabindex="-1">谁可以协作 <a class="header-anchor" href="#谁可以协作" aria-label="Permalink to &quot;谁可以协作&quot;">​</a></h2><p>从 A 后方开始，只看行动顺序表中<strong>连续的同队区间</strong>，遇到第一个不同队角色停止。</p><table tabindex="0"><thead><tr><th>行动顺序</th><th>可以提交申请的队友</th></tr></thead><tbody><tr><td>A → B → C → 敌人</td><td>B、C</td></tr><tr><td>A → B → 敌人 → C</td><td>只有 B</td></tr></tbody></table><p>同队但处于控制态的角色仍占据区间，本人不能协作。协作方须存活、可行动，并有足够的决策点和对应配额；召唤物按主人的队伍关系判断资格，但使用自己的预算。</p><p>每个协作方最多保留一份申请。提交不扣资源，确认时重新检查队列位置、状态、预算、配额、技能/物品和目标；失效申请会移除，不会因局面恢复而自动复活。</p><h2 id="双方支付什么" tabindex="-1">双方支付什么 <a class="header-anchor" href="#双方支付什么" aria-label="Permalink to &quot;双方支付什么&quot;">​</a></h2><p>以下为默认配置：</p><table tabindex="0"><thead><tr><th>角色</th><th>消耗</th><th>硬直</th></tr></thead><tbody><tr><td>A：确认协同</td><td>1 决策点，确认配额不限</td><td>3，按正常规则参与 A 的回合硬直聚合</td></tr><tr><td>B：普攻</td><td>1 决策点及普攻配额</td><td>加到 B 当前等待时间上</td></tr><tr><td>B：战技 / 魔法 / 爆发技</td><td>2 决策点及对应配额</td><td>即时技能加动作硬直；魔法使用两段式吟唱</td></tr><tr><td>B：物品</td><td>1 决策点及物品配额</td><td>加到 B 当前等待时间上</td></tr></tbody></table><p>B 使用上一次正常回合以来剩余的预算，协作不会补点，也不会把动作记进 B 上一正常回合的硬直统计。开始吟唱时检查 MP，真正释放魔法时才扣 MP。确认失败不扣双方费用；已发动的动作即使被免疫，已支付的资源也不返还。</p><p>例如，A 先做硬直为 6 的普攻，再确认一次协同，使用 2 决策点，其回合硬直为 <code>max(6, 3) + 2 = 8</code>。B 的实际伤害、治疗、资源消耗和击杀归 B，A 通过协调 B 获得非伤害辅助关系。</p><h2 id="协同魔法" tabindex="-1">协同魔法 <a class="header-anchor" href="#协同魔法" aria-label="Permalink to &quot;协同魔法&quot;">​</a></h2><p>设 B 确认前的等待时间为 <code>x</code>。开始吟唱后，队列等待时间替换为魔法的实际吟唱时间。轮到 B 时，进入一个正常的结算回合：触发回合事件、发放/回收奖励、增加行动回合计数，并执行特效钩子；处于吟唱态时直接释放，不选择新的主动行动。</p><p>结算回合不恢复 B 的决策点。其上一正常回合的硬直与配额计数已消费，会在入口清空；成功释放后，等待时间为 <code>x + 魔法动作硬直</code>。</p><p>若释放失败，失败尝试计补偿硬直，然后允许按剩余预算、配额及控制状态重新决策。再次吟唱新魔法时，新吟唱保持自身时长，<code>x</code> 顺延到最终释放或被终止时还原。新魔法是 B 自己的动作，不继承已经失败的协同申请。</p><h2 id="打断和终止" tabindex="-1">打断和终止 <a class="header-anchor" href="#打断和终止" aria-label="Permalink to &quot;打断和终止&quot;">​</a></h2><p><code>r</code> 为剩余吟唱时间，<code>c</code> 为吟唱失败补偿，默认 3。</p><table tabindex="0"><thead><tr><th>情况</th><th>B 的等待时间或处理</th></tr></thead><tbody><tr><td>在他人回合或时间流逝中被技能打断</td><td><code>x + r</code></td></tr><tr><td>在他人回合丢失全部目标</td><td><code>x + min(r, c)</code></td></tr><tr><td>没有角色正在行动时丢失全部目标</td><td><code>x + r</code>，不应用补偿上限</td></tr><tr><td>在自己的结算回合失败或释放前被打断</td><td>失败尝试计 <code>c</code>，允许正常重决，回合聚合后只加一次 <code>x</code></td></tr><tr><td>被预释放爆发技覆盖</td><td>取消原吟唱，按预释放规则插队，不另加补偿</td></tr><tr><td>死亡或移出队列</td><td>清施法状态、上下文和顺延奖励，不执行残留魔法</td></tr></tbody></table><p>只丢失部分目标时可以继续吟唱；允许空地施法的非指向性魔法，在保留目标格时也可继续。打断不会强行解除控制状态，失败也不产生有效协调辅助。</p><h2 id="自动协作" tabindex="-1">自动协作 <a class="header-anchor" href="#自动协作" aria-label="Permalink to &quot;自动协作&quot;">​</a></h2><p>AI 在正常行动决策前为符合资格的队友代交原地申请，包括手动控制的队友和召唤物。已有有效申请会保留；没有申请时评估普攻、技能和物品，不为协作移动。</p><p>宿主的行动决策优先。宿主未指定动作时，AI 优先确认有效申请，再考虑自身行动。手动回合、吟唱态和整回合接管不会自动代交；预留多少预算由游戏或 AI 策略决定。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/guide/decision-points.html">决策点</a></li><li><a href="/guide/skills-magic.html">魔法与吟唱终止</a></li><li><a href="/dev/chain-action.html">开发者接入协同行动</a></li></ul>',25)])])}const u=d(o,[["render",i]]);export{b as __pageData,u as default};
